ViewThatFits {
    HStack { icon; title }
    VStack { icon; title }
}

struct Parent: View {
    @State private var isLit = false
    var body: some View { LanternToggle(isLit: $isLit) }
}

struct LanternToggle: View {
    @Binding var isLit: Bool
    var body: some View { Toggle("Light", isOn: $isLit) }
}

NavigationStack {
    List(lessons) { lesson in
        NavigationLink(lesson.title, value: lesson)
    }
    .navigationDestination(for: Lesson.self) { LessonView(lesson: $0) }
}

guard let url = Bundle.main.url(forResource: "lessons", withExtension: "json") else {
    throw LessonLoadError.fileNotFound("lessons.json")
}
let catalog = try JSONDecoder().decode(LessonCatalog.self, from: Data(contentsOf: url))
